<?php
require_once __DIR__.'/../config/config.php';$cid=current_company_id();$pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$cid=current_company_id();$pdo->beginTransaction();try{$s=$pdo->prepare("SELECT balance FROM customers WHERE id=? AND company_id=? FOR UPDATE");$s->execute([$_POST['customer_id'],$cid]);$bal=(float)$s->fetchColumn();$amt=(float)$_POST['amount'];if($amt<=0||$amt>$bal)throw new Exception('Saldo nasabah tidak mencukupi.');$pdo->prepare("UPDATE customers SET balance=balance-? WHERE id=? AND company_id=?")->execute([$amt,$_POST['customer_id'],$cid]);$pdo->prepare("INSERT INTO withdrawals(company_id,customer_id,wallet_id,amount,withdrawal_date,description) VALUES(?,?,?,?,?,?)")->execute([$cid,$_POST['customer_id'],$_POST['wallet_id'],$amt,$_POST['withdrawal_date'],trim($_POST['description'])]);$pdo->prepare("UPDATE wallets SET balance=balance-? WHERE id=? AND company_id=?")->execute([$amt,$_POST['wallet_id'],$cid]);$pdo->commit();flash('success','Penarikan saldo berhasil.');redirect('withdrawal.php');}catch(Throwable $e){$pdo->rollBack();flash('error',$e->getMessage());redirect('withdrawal.php');}}
$c=$pdo->prepare("SELECT id,customer_no,name,balance FROM customers WHERE company_id=? AND status='active' ORDER BY name");$c->execute([$cid]);$customers=$c->fetchAll();$w=$pdo->prepare("SELECT id,name,balance FROM wallets WHERE company_id=?");$w->execute([$cid]);$wallets=$w->fetchAll();$active='withdrawal';$title='Penarikan Saldo';require __DIR__.'/../includes/header.php';?>
