<div class="card form"><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="form-grid"><div class="field"><label>Nasabah</label><select name="customer_id"><?php foreach($customers as $x):?><option value="<?=$x['id']?>"><?=e($x['customer_no'].' — '.$x['name'])?> (<?=rupiah((float)$x['balance'])?>)</option><?php endforeach;?></select></div><div class="field"><label>Kas/Rekening</label><select name="wallet_id"><?php foreach($wallets as $x):?><option value="<?=$x['id']?>"><?=e($x['name'])?> — <?=rupiah((float)$x['balance'])?></option><?php endforeach;?></select></div><div class="field"><label>Nominal</label><input type="number" min="1" step=".01" name="amount" required></div><div class="field"><label>Tanggal</label><input type="date" name="withdrawal_date" value="<?=date('Y-m-d')?>"></div><div class="field full"><label>Keterangan</label><input name="description"></div></div><div class="actions"><button class="btn danger">Proses Penarikan</button><a class="btn ghost" href="withdrawal_history.php">Riwayat Penarikan</a></div></form></div><?php require __DIR__.'/../includes/footer.php'; ?>